const USDC_ABI=['function approve(address spender,uint256 amount) returns (bool)','function balanceOf(address account) view returns (uint256)','function allowance(address owner,address spender) view returns (uint256)'];
const statusNames=['Pending','Submitted','Released','Refunded'];
const demoMilestones=[{title:'Discovery & wireframes',detail:'User flow, low-fidelity screens, scope sign-off',amount:1200,status:'Released'},{title:'Interactive prototype',detail:'Responsive prototype with checkout flow',amount:1800,status:'Submitted'},{title:'Production handoff',detail:'Final screens, design system, developer notes',amount:3200,status:'Pending'}];
const app={artifact:null,provider:null,signer:null,account:null,contract:null,contractAddress:localStorage.getItem('scopepay-contract')||'',dealId:localStorage.getItem('scopepay-deal')||'',deal:null,milestones:[],events:[],importedProof:null,demoReleased:1200,demoDisputed:false,busy:false,syncing:false,syncTimer:null};
const $=s=>document.querySelector(s);const short=a=>a?`${a.slice(0,6)}…${a.slice(-4)}`:'—';const money=n=>new Intl.NumberFormat('en-US',{maximumFractionDigits:2}).format(n);const escapeHtml=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
function proofKey(){return `scopepay-proof-${app.contractAddress}-${app.dealId}`}
function encodeProof(value){const bytes=new TextEncoder().encode(JSON.stringify(value));let binary='';for(const byte of bytes)binary+=String.fromCharCode(byte);return btoa(binary).replaceAll('+','-').replaceAll('/','_').replace(/=+$/,'')}
function decodeProof(value){try{const binary=atob(value.replaceAll('-','+').replaceAll('_','/')+'==='.slice((value.length+3)%4));const bytes=Uint8Array.from(binary,char=>char.charCodeAt(0));const parsed=JSON.parse(new TextDecoder().decode(bytes));return parsed?.version===1?parsed:null}catch{return null}}
function readLocalMeta(){try{const stored=JSON.parse(localStorage.getItem(`scopepay-meta-${app.contractAddress}-${app.dealId}`)||'null');if(stored)return stored;const featured=app.artifact?.deployment;if(String(app.dealId)===String(featured?.featuredDealId)&&app.contractAddress.toLowerCase()===String(featured?.address||'').toLowerCase())return featured.featuredTerms||null;return null}catch{return null}}
function readLocalEvidence(){try{return JSON.parse(localStorage.getItem(proofKey())||'[]')}catch{return[]}}
function validTerms(value){return value&&typeof value.title==='string'&&value.title.length<=120&&Array.isArray(value.names)&&Array.isArray(value.details)&&value.names.length<=12&&value.details.length<=12&&value.names.every(x=>typeof x==='string'&&x.length<=120)&&value.details.every(x=>typeof x==='string'&&x.length<=300)}
function proofContext(){const imported=app.importedProof&&String(app.importedProof.contract||'').toLowerCase()===app.contractAddress.toLowerCase()&&String(app.importedProof.deal)===String(app.dealId)?app.importedProof:null;const candidate=imported?.terms||readLocalMeta();const termsVerified=!!(app.deal&&validTerms(candidate)&&ethers.id(JSON.stringify(candidate)).toLowerCase()===String(app.deal.termsCommitment).toLowerCase());const combined=[...(Array.isArray(imported?.evidence)?imported.evidence:[]),...(Array.isArray(readLocalEvidence())?readLocalEvidence():[])];const evidence=new Map();if(app.deal)for(const item of combined){const index=Number(item?.milestone);const text=typeof item?.text==='string'?item.text:'';if(Number.isInteger(index)&&index>=0&&index<app.milestones.length&&text.length<=2000&&ethers.id(text).toLowerCase()===String(app.milestones[index].evidence).toLowerCase())evidence.set(index,{milestone:index,text,commitment:ethers.id(text)})}return{terms:termsVerified?candidate:null,termsVerified,evidence}}
function makeProofPack(){const context=proofContext();return{version:1,contract:app.contractAddress,deal:String(app.dealId),terms:context.terms,evidence:[...context.evidence.values()]}}
function evidenceMarkup(item){if(!item)return'';let detail;try{const url=new URL(item.text);detail=/^https?:$/.test(url.protocol)?`<a href="${escapeHtml(url.href)}" target="_blank" rel="noreferrer">Open delivery ↗</a>`:`<span>${escapeHtml(item.text.slice(0,160))}</span>`}catch{detail=`<span>${escapeHtml(item.text.slice(0,160))}</span>`}return`<p class="proof-note"><b>✓ Evidence verified</b>${detail}</p>`}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2600)}function explain(error){return error?.info?.error?.message||error?.shortMessage||error?.reason||error?.message||'The transaction did not complete.'}
async function init(){app.artifact=await fetch('/contract.json').then(r=>r.json());app.importedProof=decodeProof(query.get('proof')||'');if(!app.contractAddress)app.contractAddress=app.artifact.deployment?.address||'';if(app.dealId===''&&app.artifact.deployment?.featuredDealId!==undefined)app.dealId=String(app.artifact.deployment.featuredDealId);$('#contractAddressInput').value=app.contractAddress;wire();if(app.contractAddress)await connectContract(false);if(app.contract&&app.dealId!=='')await loadDeal(app.dealId);else renderDemo();startLiveSync()}
function wire(){$('#walletButton').onclick=connectWallet;$('#setupButton').onclick=()=>$('#setupDialog').showModal();$('#newDealButton').onclick=openNewDeal;$('#loadDealButton').onclick=()=>$('#loadDealDialog').showModal();$('#useContractButton').onclick=useExistingContract;$('#deployContractButton').onclick=deployContract;$('#createDealButton').onclick=createDeal;$('#confirmLoadDeal').onclick=loadDealFromInput;$('#activityNav').onclick=openActivity;$('#judgeActivity').onclick=openActivity;$('#dealsNav').onclick=closeActivity;$('#closeActivity').onclick=closeActivity;$('#copyLink').onclick=copyDealLink;$('#copyProofLink').onclick=copyProofLink;$('#confirmCopyShare').onclick=copyShareValue;$('#confirmApprove').onclick=approveCurrent;$('#confirmEvidence').onclick=submitEvidence;$('#confirmDispute').onclick=openDispute;$('#confirmResolve').onclick=resolveDispute;window.ethereum?.on?.('accountsChanged',handleAccountsChanged);window.ethereum?.on?.('chainChanged',handleChainChanged);document.addEventListener('visibilitychange',()=>{if(!document.hidden)syncLiveDeal()});registerWebMCP()}
async function handleAccountsChanged(accounts){try{if(!accounts?.length){app.provider=null;app.signer=null;app.account=null;app.contract=null;$('#walletButton').textContent='Connect wallet';await connectContract(false);if(app.dealId!=='')await loadDeal(app.dealId);toast('Wallet disconnected — read-only mode');return}await ensureNetwork();app.provider=new ethers.BrowserProvider(window.ethereum);app.signer=await app.provider.getSigner(accounts[0]);app.account=await app.signer.getAddress();$('#walletButton').textContent=short(app.account);if(app.contractAddress)await connectContract(false);if(app.dealId!=='')await loadDeal(app.dealId);toast(`Switched to ${getRole()} wallet`)}catch(e){toast(explain(e))}}
async function handleChainChanged(chainId){if(!app.artifact)return;if(String(chainId).toLowerCase()!==app.artifact.network.chainHex.toLowerCase()){app.provider=null;app.signer=null;app.account=null;app.contract=null;$('#walletButton').textContent='Switch network';await connectContract(false);if(app.dealId!=='')await loadDeal(app.dealId);toast('Switch to Arbitrum Sepolia to sign transactions');return}const accounts=await window.ethereum.request({method:'eth_accounts'});await handleAccountsChanged(accounts)}
function startLiveSync(){clearInterval(app.syncTimer);app.syncTimer=setInterval(syncLiveDeal,12000)}
async function syncLiveDeal(){if(app.syncing||app.busy||!app.contract||app.dealId===''||document.hidden)return;app.syncing=true;try{await loadDeal(app.dealId)}finally{app.syncing=false}}
function openActivity(){const panel=$('#activityPanel');panel.classList.remove('hidden');$('#activityNav').classList.add('active');$('#activityNav').setAttribute('aria-expanded','true');$('#dealsNav').classList.remove('active');requestAnimationFrame(()=>{panel.scrollIntoView({behavior:'smooth',block:'start'});panel.focus({preventScroll:true})})}
function closeActivity(){const panel=$('#activityPanel');panel.classList.add('hidden');$('#activityNav').classList.remove('active');$('#activityNav').setAttribute('aria-expanded','false');$('#dealsNav').classList.add('active');document.querySelector('.shell').scrollIntoView({behavior:'smooth',block:'start'})}
function walletErrorCode(error){return Number(error?.code??error?.data?.code??error?.data?.originalError?.code??error?.error?.code)}
function walletErrorText(error){return [error?.message,error?.data?.message,error?.data?.originalError?.message,error?.error?.message].filter(Boolean).join(' ')}
async function ensureNetwork(){const target=app.artifact.network.chainHex.toLowerCase();const selected=String(await window.ethereum.request({method:'eth_chainId'})).toLowerCase();if(selected===target)return;try{await window.ethereum.request({method:'wallet_switchEthereumChain',params:[{chainId:target}]})}catch(error){const unknown=walletErrorCode(error)===4902||/unrecognized|unknown chain|chain.+not added|add.+chain/i.test(walletErrorText(error));if(!unknown)throw error;await window.ethereum.request({method:'wallet_addEthereumChain',params:[{chainId:target,chainName:'Arbitrum Sepolia',nativeCurrency:{name:'Arbitrum Sepolia Ether',symbol:'ETH',decimals:18},rpcUrls:[app.artifact.network.rpc],blockExplorerUrls:[app.artifact.network.explorer]}]});const afterAdd=String(await window.ethereum.request({method:'eth_chainId'})).toLowerCase();if(afterAdd!==target)await window.ethereum.request({method:'wallet_switchEthereumChain',params:[{chainId:target}]})}const confirmed=String(await window.ethereum.request({method:'eth_chainId'})).toLowerCase();if(confirmed!==target)throw new Error('Select Arbitrum Sepolia in your wallet, then try again.')}
async function connectWallet(){if(!window.ethereum)return toast('Install MetaMask or Rabby to use live mode');try{await window.ethereum.request({method:'eth_requestAccounts'});await ensureNetwork();app.provider=new ethers.BrowserProvider(window.ethereum);app.signer=await app.provider.getSigner();app.account=await app.signer.getAddress();$('#walletButton').textContent=short(app.account);if(app.contractAddress)await connectContract(true);if(app.dealId!=='')await loadDeal(app.dealId);else renderDemo();toast('Wallet connected on Arbitrum Sepolia')}catch(e){toast(explain(e))}}
async function connectContract(show=true){try{const rpc=app.provider||new ethers.JsonRpcProvider(app.artifact.network.rpc);const code=await rpc.getCode(app.contractAddress);if(code==='0x')throw new Error('No contract was found at that address.');const candidate=new ethers.Contract(app.contractAddress,app.artifact.abi,app.signer||rpc);const paymentToken=await candidate.paymentToken();if(paymentToken.toLowerCase()!==app.artifact.usdc.address.toLowerCase())throw new Error('This contract is not configured for official Arbitrum Sepolia USDC.');app.contract=candidate;localStorage.setItem('scopepay-contract',app.contractAddress);$('#contractAddressInput').value=app.contractAddress;$('#contractLink').href=`${app.artifact.network.explorer}/address/${app.contractAddress}`;$('#contractLink').classList.remove('hidden');setMode();if(show)toast('Live ScopePay contract selected');return true}catch(e){app.contract=null;if(show)toast(explain(e));return false}}
async function useExistingContract(){const value=$('#contractAddressInput').value.trim();if(!ethers.isAddress(value))return toast('Enter a valid contract address');app.contractAddress=value;if(await connectContract()){$('#setupDialog').close();if(app.dealId!=='')await loadDeal(app.dealId)}}
async function deployContract(){if(!app.signer){$('#setupDialog').close();return connectWallet()}setBusy(true,'Deploying contract…');try{const factory=new ethers.ContractFactory(app.artifact.abi,app.artifact.bytecode,app.signer);const contract=await factory.deploy(app.artifact.usdc.address);toast('Deployment sent — waiting for confirmation');await contract.waitForDeployment();app.contractAddress=await contract.getAddress();app.contract=contract;localStorage.setItem('scopepay-contract',app.contractAddress);$('#contractAddressInput').value=app.contractAddress;$('#setupDialog').close();setMode();$('#contractLink').href=`${app.artifact.network.explorer}/address/${app.contractAddress}`;$('#contractLink').classList.remove('hidden');toast('ScopePay is live on Arbitrum Sepolia')}catch(e){toast(explain(e))}finally{setBusy(false)}}
function openNewDeal(){if(!app.account)return connectWallet();if(!app.contract)return $('#setupDialog').showModal();$('#newDealDialog').showModal()}
async function createDeal(){if(!app.signer||!app.contract)return toast('Connect a wallet and contract first');const worker=$('#newWorker').value.trim(),arbiter=$('#newArbiter').value.trim(),title=$('#newTitle').value.trim();const values=[...document.querySelectorAll('.amountInput')].map(i=>i.value.trim());if(!ethers.isAddress(worker)||!ethers.isAddress(arbiter))return toast('Enter valid freelancer and arbiter addresses');if(!title||values.some(v=>!v||Number(v)<=0))return toast('Complete the title and milestone amounts');const amounts=values.map(v=>ethers.parseUnits(v,6));const total=amounts.reduce((a,b)=>a+b,0n);const token=new ethers.Contract(app.artifact.usdc.address,USDC_ABI,app.signer);setBusy(true,'Checking USDC…');try{const balance=await token.balanceOf(app.account);if(balance<total)throw new Error(`You need ${money(Number(ethers.formatUnits(total,6)))} test USDC. Use Circle's faucet first.`);const allowance=await token.allowance(app.account,app.contractAddress);if(allowance<total){toast('Approve the escrow to use this test USDC');await(await token.approve(app.contractAddress,total)).wait()}const now=Math.floor(Date.now()/1000);const due=[now+7*86400,now+14*86400,now+21*86400];const meta={title,names:['Direction','Working delivery','Final handoff'],details:['Agree the approach and scope','Deliver the working result','Complete revisions and handoff'],amounts:values};const terms=ethers.id(JSON.stringify(meta));toast('Create and fund the deal in your wallet');const receipt=await(await app.contract.createDeal(worker,arbiter,amounts,due,terms)).wait();const event=receipt.logs.map(l=>{try{return app.contract.interface.parseLog(l)}catch{return null}}).find(x=>x?.name==='DealCreated');const id=event.args.dealId.toString();localStorage.setItem(`scopepay-meta-${app.contractAddress}-${id}`,JSON.stringify(meta));localStorage.setItem('scopepay-deal',id);app.dealId=id;$('#newDealDialog').close();await loadDeal(id);toast(`Deal #${id} funded on Arbitrum`)}catch(e){toast(explain(e))}finally{setBusy(false)}}
async function loadDealFromInput(){const id=$('#dealIdInput').value.trim();if(!/^\d+$/.test(id))return toast('Enter a whole-number deal ID');if(!app.contract){$('#loadDealDialog').close();return $('#setupDialog').showModal()}await loadDeal(id);if(app.deal)$('#loadDealDialog').close()}
async function loadDeal(id){try{const raw=await app.contract.deals(id);if(raw.client===ethers.ZeroAddress)throw new Error('That deal does not exist on this contract.');app.deal={client:raw.client,worker:raw.worker,arbiter:raw.arbiter,termsCommitment:raw.termsCommitment,total:Number(ethers.formatUnits(raw.totalDeposited,6)),remaining:Number(ethers.formatUnits(raw.remaining,6)),current:Number(raw.currentMilestone),count:Number(raw.milestoneCount),disputed:raw.disputed,closed:raw.closed};const rows=await Promise.all(Array.from({length:app.deal.count},(_,i)=>app.contract.milestones(id,i)));app.milestones=rows.map(m=>({amount:Number(ethers.formatUnits(m.amount,6)),dueAt:Number(m.dueAt),status:statusNames[Number(m.status)],evidence:m.evidenceCommitment}));app.dealId=String(id);localStorage.setItem('scopepay-deal',app.dealId);await loadEvents();renderLive()}catch(e){app.deal=null;toast(explain(e))}}
async function loadEvents(){const names=['DealCreated','MilestoneSubmitted','MilestoneReleased','DisputeOpened','DisputeResolved','DealCancelled'];const provider=app.provider||app.contract.runner.provider;const latest=await provider.getBlockNumber();const fromBlock=Math.min(latest,Number(app.artifact.deployment?.startBlock??Math.max(0,latest-200000)));const lists=await Promise.all(names.map(async name=>{try{return await app.contract.queryFilter(app.contract.filters[name](app.dealId),fromBlock)}catch{return[]}}));app.events=lists.flat().sort((a,b)=>Number(b.blockNumber-a.blockNumber))}
function meta(){return proofContext().terms}
function renderDemo(){if(app.deal)return renderLive();renderPage({title:'Mobile storefront redesign',crumb:'GUIDED DEMO / #SP-2048',description:'Explore the deal flow, then connect a wallet to create a funded escrow on Arbitrum.',total:6200,remaining:6200-app.demoReleased,paid:app.demoReleased,refunded:0,milestones:demoMilestones.map(m=>({...m})),client:'0x71C4000000000000000000000000000000008A20',worker:'0xA90E0000000000000000000000000000000041F2',arbiter:'0x5B17000000000000000000000000000000000D92',terms:'0x3c7f…91e2',role:'Demo client',disputed:app.demoDisputed,closed:false,current:1,demo:true});setMode()}
function moneyFlow(){let paid=0,refunded=0;const resolutions=new Map();for(const event of app.events){if(event.fragment.name==='MilestoneReleased')paid+=Number(ethers.formatUnits(event.args.amount,6));if(event.fragment.name==='DisputeResolved'){const workerAmount=Number(ethers.formatUnits(event.args.workerAmount,6)),clientAmount=Number(ethers.formatUnits(event.args.clientAmount,6));paid+=workerAmount;refunded+=clientAmount;resolutions.set(Number(event.args.milestone),{workerAmount,clientAmount})}if(event.fragment.name==='DealCancelled')refunded+=Number(ethers.formatUnits(event.args.refundedAmount,6))}return{paid,refunded,resolutions}}
function renderLive(){const context=proofContext(),m=context.terms,flow=moneyFlow();renderPage({title:m?.title||`On-chain deal #${app.dealId}`,crumb:`LIVE ON ARBITRUM / DEAL #${app.dealId}`,description:'Every approval, release, dispute, and resolution below is read directly from the ScopePay contract.',total:app.deal.total,remaining:app.deal.remaining,paid:flow.paid,refunded:flow.refunded,milestones:app.milestones.map((x,i)=>{const resolution=flow.resolutions.get(i);let statusLabel=x.status;if(resolution)statusLabel=`Resolved · ${money(resolution.workerAmount)} paid · ${money(resolution.clientAmount)} refunded`;else if(app.deal.closed&&x.status==='Pending')statusLabel='Cancelled · funds returned';return{...x,statusLabel,title:m?.names?.[i]||`Milestone ${i+1}`,detail:m?.details?.[i]||new Date(x.dueAt*1000).toLocaleDateString(),proof:context.evidence.get(i)}}),client:app.deal.client,worker:app.deal.worker,arbiter:app.deal.arbiter,terms:short(app.deal.termsCommitment),termsVerified:context.termsVerified,evidenceCount:context.evidence.size,role:getRole(),disputed:app.deal.disputed,closed:app.deal.closed,current:app.deal.current,demo:false});setMode()}
function renderPage(d){$('#dealCrumb').textContent=d.crumb;$('#dealTitle').textContent=d.title;$('#dealDescription').textContent=d.description;$('#remaining').textContent=money(d.remaining);$('#funded').textContent=`${money(d.total)} USDC funded`;const settled=d.total-d.remaining,paid=d.paid??settled,refunded=d.refunded??0;$('#flowSummary').innerHTML=`<b>${money(paid)} USDC</b> paid${refunded?` · <b>${money(refunded)} USDC</b> refunded`:''}`;$('#progress').style.width=`${d.total?settled/d.total*100:0}%`;$('#milestoneCount').textContent=d.closed?'Deal settled':`${d.milestones.filter(m=>m.status==='Released').length} of ${d.milestones.length} paid`;$('#milestones').innerHTML=d.milestones.map((m,i)=>`<article class="milestone ${m.status.toLowerCase()} ${i===d.current&&!d.closed?'active':''}"><span class="index">${String(i+1).padStart(2,'0')}</span><div><h3>${escapeHtml(m.title)}</h3><p>${escapeHtml(m.detail)}</p>${evidenceMarkup(m.proof)}</div><div class="amount">${money(m.amount)} USDC<span class="status ${m.status.toLowerCase()}">${escapeHtml(d.disputed&&i===d.current?'Disputed':m.statusLabel||m.status)}</span></div></article>`).join('');$('#clientAddress').textContent=short(d.client);$('#workerAddress').textContent=short(d.worker);$('#arbiterAddress').textContent=short(d.arbiter);$('#userRole').textContent=d.role;$('#termsHash').textContent=d.terms;$('#termsState').textContent=d.termsVerified?'Proof verified':'Committed';$('#proofStatus').textContent=d.demo?'Demo terms are illustrative.':d.termsVerified?(d.evidenceCount?`${d.evidenceCount} evidence item${d.evidenceCount===1?'':'s'} verified against the on-chain commitments.`:'Readable terms verified. Delivery evidence stays private unless its author shares it.'):'Add a proof link to reveal and verify the committed terms.';$('#secureBadge').innerHTML=d.demo?'<i></i> Demonstration state':'<i></i> Verified contract state';renderAction(d);renderActivity(d.demo)}
function renderAction(d){const current=d.milestones[d.current];let kicker='DEAL STATUS',icon='✓',title='Deal completed',text='All funds have been released or resolved.',controls='';if(d.disputed){icon='!';title='Escrow frozen';text=d.role==='Arbiter'?'Review the evidence and decide the current milestone split.':'The named arbiter must resolve this dispute.';controls=d.role==='Arbiter'?'<button class="primary wide" onclick="document.querySelector(\'#resolveDialog\').showModal()">Resolve dispute</button>':''}else if(!d.closed&&current){icon=String(d.current+1).padStart(2,'0');title=current.title;if(d.demo||(d.role==='Client'&&current.status==='Submitted')){kicker='NEEDS YOUR REVIEW';text='Review the submitted evidence before releasing this milestone.';controls=`<button class="primary wide" onclick="window.requestApprove()">Approve & release ${money(current.amount)} USDC</button><button class="ghost wide" onclick="window.requestDispute()">Open a dispute</button>`}else if(d.role==='Worker'&&current.status==='Pending'){kicker='READY TO DELIVER';text='Commit a delivery note or evidence link for the client to review.';controls='<button class="primary wide" onclick="document.querySelector(\'#evidenceDialog\').showModal()">Submit milestone</button><button class="ghost wide" onclick="window.requestDispute()">Open a dispute</button>'}else{kicker='IN PROGRESS';text=current.status==='Submitted'?'Waiting for the client to review this submission.':'Waiting for the freelancer to submit this milestone.';if(d.role==='Client'||d.role==='Worker')controls='<button class="ghost wide" onclick="window.requestDispute()">Open a dispute</button>'}}$('#actionKicker').textContent=kicker;$('#actionIcon').textContent=icon;$('#actionTitle').textContent=title;$('#actionText').textContent=text;$('#actionControls').innerHTML=controls;$('#actionFine').textContent=d.demo?'Demo actions are local. Live mode asks your wallet to sign each contract transaction.':'Live action: your wallet signs and Arbitrum confirms the result.'}
function renderActivity(demo){const list=demo?[{text:'Interactive prototype submitted for review',time:'Today, 10:42'},{text:'Discovery & wireframes approved',time:'Sep 18, 14:08'},{text:'6,200 USDC funded into escrow',time:'Sep 14, 09:12'}]:app.events.map(e=>({text:e.fragment.name.replace(/([A-Z])/g,' $1').trim(),time:`Block ${e.blockNumber}`,url:`${app.artifact.network.explorer}/tx/${e.transactionHash}`}));$('#activityList').innerHTML=list.length?list.map(x=>`<div class="activity-row"><i></i><strong>${x.url?`<a href="${x.url}" target="_blank" rel="noreferrer">${x.text} ↗</a>`:x.text}</strong><span>${x.time}</span></div>`).join(''):'<p class="fine">No contract events found yet.</p>'}
function setMode(){const live=!!app.contract;$('#modeLabel').textContent=live?'Live contract connected':'Guided demo';$('#modeDetail').textContent=live?`${short(app.contractAddress)} · Circle test USDC · ${app.account?short(app.account):'wallet not connected'} · auto-sync on`:'Connect a wallet and configure the contract to use live testnet USDC.'}function getRole(){if(!app.account||!app.deal)return app.account?'Viewer':'Viewer';const a=app.account.toLowerCase();if(a===app.deal.client.toLowerCase())return'Client';if(a===app.deal.worker.toLowerCase())return'Worker';if(a===app.deal.arbiter.toLowerCase())return'Arbiter';return'Viewer'}function setBusy(value,label='Working…'){app.busy=value;document.querySelectorAll('button').forEach(b=>b.disabled=value);if(value)toast(label)}
window.requestApprove=()=>$('#approveDialog').showModal();window.requestDispute=()=>$('#disputeDialog').showModal();
async function approveCurrent(){if(!app.deal){app.demoReleased=3000;demoMilestones[1].status='Released';$('#approveDialog').close();renderDemo();return toast('Guided milestone released')}await transact('Release milestone',()=>app.contract.approveMilestone(app.dealId,app.deal.current),'#approveDialog')}
async function submitEvidence(){const text=$('#evidenceInput').value.trim();if(text.length<8)return toast('Add a useful delivery note or evidence URL');const milestone=app.deal?.current;const complete=await transact('Submit evidence',()=>app.contract.submitMilestone(app.dealId,milestone,ethers.id(text)),'#evidenceDialog');if(complete){const items=readLocalEvidence().filter(item=>Number(item?.milestone)!==milestone);items.push({milestone,text,commitment:ethers.id(text)});localStorage.setItem(proofKey(),JSON.stringify(items));renderLive();toast('Evidence committed — proof link is ready')}}
async function openDispute(){const reason=$('#disputeReason').value.trim();if(reason.length<8)return toast('Give a clear reason of at least 8 characters');if(!app.deal){app.demoDisputed=true;$('#disputeDialog').close();renderDemo();return toast('Guided escrow frozen')}await transact('Open dispute',()=>app.contract.openDispute(app.dealId,ethers.id(reason)),'#disputeDialog')}
async function resolveDispute(){const value=$('#workerAwardInput').value.trim();if(value===''||Number(value)<0)return toast('Enter a valid USDC amount');await transact('Resolve dispute',()=>app.contract.resolveDispute(app.dealId,ethers.parseUnits(value,6)),'#resolveDialog')}
async function transact(label,send,dialog){if(!app.signer){toast('Connect the role wallet first');return false}setBusy(true,`${label} — confirm in your wallet`);try{const tx=await send();toast('Transaction sent — waiting for Arbitrum');await tx.wait();$(dialog).close();await loadDeal(app.dealId);toast(`${label} confirmed`);return true}catch(e){toast(explain(e));return false}finally{setBusy(false)}}
function baseDealUrl(){const url=new URL(location.href);url.searchParams.delete('proof');if(app.contractAddress)url.searchParams.set('contract',app.contractAddress);if(app.dealId!=='')url.searchParams.set('deal',app.dealId);return url}
async function copyText(value){try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(value);return true}}catch{}const area=document.createElement('textarea');area.value=value;area.setAttribute('readonly','');area.style.position='fixed';area.style.opacity='0';document.body.append(area);area.select();let copied=false;try{copied=document.execCommand('copy')}catch{}area.remove();return copied}
function showShareLink(title,description,value){$('#shareTitle').textContent=title;$('#shareDescription').textContent=description;$('#shareLinkOutput').value=value;$('#shareDialog').showModal()}
async function copyShareValue(){const output=$('#shareLinkOutput');const copied=await copyText(output.value);if(copied)toast('Link copied');else{output.focus();output.select();toast('Select the link and copy it manually')}}
async function copyDealLink(){const value=baseDealUrl().toString();showShareLink('Share on-chain state','Anyone with this link can inspect the current deal state directly from the ScopePay contract.',value);if(await copyText(value))toast('On-chain state link copied')}
async function copyProofLink(){if(!app.deal)return toast('Load a live deal before copying proof');const pack=makeProofPack();if(!pack.terms)return toast('The readable terms on this device do not match the on-chain commitment');const url=baseDealUrl();url.searchParams.set('proof',encodeProof(pack));showShareLink('Share verified proof','This link carries the readable terms and evidence, then verifies them against the commitments stored on Arbitrum.',url.toString());if(await copyText(url.toString()))toast('Verified proof link copied')}
function registerWebMCP(){if(!document.modelContext?.registerTool)return;const read={name:'read_active_scopepay_deal',title:'Read active ScopePay deal',description:'Return the deal currently visible in ScopePay without changing it.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:async()=>app.deal?{mode:'live',dealId:app.dealId,remaining:app.deal.remaining,currentMilestone:app.deal.current,disputed:app.deal.disputed,closed:app.deal.closed}:{mode:'guided_demo',released:app.demoReleased,disputed:app.demoDisputed}};const start={name:'start_scopepay_deal_creation',title:'Start a ScopePay deal',description:'Open the new funded deal form. The user must review details and approve wallet transactions.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async()=>{openNewDeal();return{status:'form_opened',walletRequired:true}}};Promise.resolve(document.modelContext.registerTool(read)).catch(()=>{});Promise.resolve(document.modelContext.registerTool(start)).catch(()=>{})}
const query=new URLSearchParams(location.search);if(query.get('contract')){app.contractAddress=query.get('contract');localStorage.setItem('scopepay-contract',app.contractAddress)}if(query.get('deal')){app.dealId=query.get('deal');localStorage.setItem('scopepay-deal',app.dealId)}init();
